mapper.update:
UPDATE flow_run
SET run_status = #{runStatus},
    context_snapshot = #{contextSnapshot},
    total_cost_ms = #{totalCostMs},
    error_msg = #{errorMsg}
WHERE run_id = #{runId}

mapper.select:
SELECT 
FROM flow_run

    flow_id = #{flowId}

ORDER BY run_id DESC
LIMIT #{offset}, #{pageSize}
